/**
 * Gemini Hook Event Types
 * Based on official Gemini CLI documentation
 * https://github.com/principle-md/gemini-cli/blob/add-hooks-feature/docs/hooks.md
 */

/**
 * Common fields present in all Gemini hook events
 */
export interface GeminiHookCommon {
  session_id: string;
  transcript_path: string;
  working_directory: string;
  hook_event_name: string;
}

/**
 * PreToolUse event - before tool execution
 */
export interface GeminiPreToolUseEvent extends GeminiHookCommon {
  hook_event_name: 'PreToolUse';
  tool_name: string;
  tool_use_input: string; // JSON string of tool parameters
}

/**
 * PostToolUse event - after tool execution
 */
export interface GeminiPostToolUseEvent extends GeminiHookCommon {
  hook_event_name: 'PostToolUse';
  tool_name: string;
  tool_use_input: string; // JSON string of tool parameters
  tool_response: unknown; // Tool response structure varies by tool
  duration?: number; // Execution duration in milliseconds
  result_size?: number; // Size of result in bytes
}

/**
 * Notification event
 */
export interface GeminiNotificationEvent extends GeminiHookCommon {
  hook_event_name: 'Notification';
  message: string;
}

/**
 * UserPromptSubmit event - when user submits a prompt
 */
export interface GeminiUserPromptSubmitEvent extends GeminiHookCommon {
  hook_event_name: 'UserPromptSubmit';
  prompt: string;
}

/**
 * Stop event - when Gemini finishes responding
 */
export interface GeminiStopEvent extends GeminiHookCommon {
  hook_event_name: 'Stop';
  trigger?: 'user' | 'error' | 'complete';
  reason?: string;
  stop_hook_active?: boolean;
}

/**
 * SubagentStop event - when a subagent (Task tool) finishes
 */
export interface GeminiSubagentStopEvent extends GeminiHookCommon {
  hook_event_name: 'SubagentStop';
  task_id?: string;
  stop_hook_active?: boolean;
}

/**
 * PreCompact event - before context compaction
 */
export interface GeminiPreCompactEvent extends GeminiHookCommon {
  hook_event_name: 'PreCompact';
  trigger: 'manual' | 'auto';
  custom_instructions?: string;
  context_size?: number;
}

/**
 * SessionStart event - when session starts or resumes
 */
export interface GeminiSessionStartEvent extends GeminiHookCommon {
  hook_event_name: 'SessionStart';
  source: 'startup' | 'resume' | 'clear';
  resume_from?: string; // Session ID if resuming
}

/**
 * Union type of all Gemini hook events
 */
export type GeminiHookEvent =
  | GeminiPreToolUseEvent
  | GeminiPostToolUseEvent
  | GeminiNotificationEvent
  | GeminiUserPromptSubmitEvent
  | GeminiStopEvent
  | GeminiSubagentStopEvent
  | GeminiPreCompactEvent
  | GeminiSessionStartEvent;

/**
 * Type guards for Gemini events
 */
export function isGeminiPreToolUse(data: unknown): data is GeminiPreToolUseEvent {
  return isGeminiEvent(data) && data.hook_event_name === 'PreToolUse';
}

export function isGeminiPostToolUse(data: unknown): data is GeminiPostToolUseEvent {
  return isGeminiEvent(data) && data.hook_event_name === 'PostToolUse';
}

export function isGeminiNotification(data: unknown): data is GeminiNotificationEvent {
  return isGeminiEvent(data) && data.hook_event_name === 'Notification';
}

export function isGeminiUserPromptSubmit(data: unknown): data is GeminiUserPromptSubmitEvent {
  return isGeminiEvent(data) && data.hook_event_name === 'UserPromptSubmit';
}

export function isGeminiStop(data: unknown): data is GeminiStopEvent {
  return isGeminiEvent(data) && data.hook_event_name === 'Stop';
}

export function isGeminiSubagentStop(data: unknown): data is GeminiSubagentStopEvent {
  return isGeminiEvent(data) && data.hook_event_name === 'SubagentStop';
}

export function isGeminiPreCompact(data: unknown): data is GeminiPreCompactEvent {
  return isGeminiEvent(data) && data.hook_event_name === 'PreCompact';
}

export function isGeminiSessionStart(data: unknown): data is GeminiSessionStartEvent {
  return isGeminiEvent(data) && data.hook_event_name === 'SessionStart';
}

/**
 * Base type guard for Gemini events
 */
export function isGeminiEvent(data: unknown): data is GeminiHookEvent {
  return (
    typeof data === 'object' &&
    data !== null &&
    'session_id' in data &&
    'transcript_path' in data &&
    'working_directory' in data &&
    'hook_event_name' in data
  );
}

/**
 * Known Gemini tool names
 * Based on the documentation
 */
export const GEMINI_TOOLS = {
  // File operations
  READ_FILE: 'read_file',
  WRITE_FILE: 'write_file',
  EDIT_FILE: 'str_replace_editor',

  // Search operations
  BASH: 'bash',
  GLOB: 'glob',
  GREP: 'grep',
  LIST_FILES: 'list_files',

  // Web operations
  WEB_SEARCH: 'web_search',
  GET_URL: 'get_url',

  // Task management
  TASK: 'task',
  TODO_UPDATE: 'todo_update',

  // Other
  ASK_FOLLOWUP: 'ask_followup_question',
  ATTEMPT_COMPLETION: 'attempt_completion',
} as const;

export type GeminiToolName = (typeof GEMINI_TOOLS)[keyof typeof GEMINI_TOOLS] | string;
